#pragma once

// Runtime support text compiled into every program generated by
// IrToOptCppEmitter. It mirrors the VM's observable behavior: the same fault
// messages (reported as `VM error: ...` with exit code 3), the same heap
// address encoding, the same file-handle packing and I/O error codes. The heap is
// the VM's own allocator (VmHeapCore) and string heap (VmTextHeap), pasted in between the two halves below, with the
// per-thread arenas (VmHeapArenas) after them: a program runs on arena 0, which is the VM's heap exactly until a
// second thread gets an arena. A spawned task runs on a thread of its own (OptCppTaskRuntime, pasted in only for a
// module with task opcodes), so everything here that is not per thread (`Rt`) is safe to call from several threads.

namespace primec {

inline constexpr const char *OptCppRuntimeHeaders = R"CPP(#include <algorithm>
#include <atomic>
#include <bit>
#include <cerrno>
#include <charconv>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fcntl.h>
#include <string>
#include <string_view>
#include <iterator>
#include <map>
#include <mutex>
#include <new>
#include <pthread.h>
#include <set>
#include <sys/mman.h>
#include <unistd.h>
#include <utility>
#include <vector>

)CPP";

// Follows `namespace {` and VmHeapCoreSource (the emitter writes the host function
// declarations between OptCppRuntimeHeaders and the namespace, so they keep C linkage).
inline constexpr const char *OptCppRuntimePreamble = R"CPP(
constexpr uint64_t PsHeapTag = uint64_t{1} << 63;
constexpr uint64_t PsSlotBytes = 16;
constexpr unsigned PsMaxCallDepth = 4096;
constexpr uint32_t PsFileReadEof = 65536u;

// A live frame that can be addressed: its first local in the one numbering of all live locals the VM uses (the
// caller's base plus the caller's local count) and its slots.
struct PsFrameRef {
  uint64_t base;
  uint64_t count;
  uint64_t *slots;
};

// The state of one thread: the main thread's lives in `main`, a task's on its own thread's stack.
struct Rt {
  int argc;
  char **argv;
  unsigned depth;
  // The heap and string heap of this thread's arena, and all the arenas of the program.
  VmHeapCore &heap;
  VmTextHeap &text;
  VmHeapArenas &arenas;
  // The base the next call's locals get, and the frames whose locals have addresses, innermost last.
  uint64_t localsTop = 0;
  unsigned frameCount = 0;
  PsFrameRef frames[PsMaxCallDepth + 1] = {};
};

// A fault ends the program from whichever thread it happens on. Only the first one reports (a thread that faults
// meanwhile waits for the exit), and it leaves through _Exit: exit would run static destructors and atexit
// handlers while the other threads still run.
[[noreturn]] void ps_fault(const char *message) {
  static std::atomic<bool> faulted{false};
  if (faulted.exchange(true)) {
    for (;;) {
      ::pause();
    }
  }
  std::fflush(stdout);
  std::fprintf(stderr, "VM error: %s\n", message);
  std::fflush(stderr);
  std::_Exit(3);
}

[[noreturn]] void ps_fault(const std::string &message) {
  ps_fault(message.c_str());
}

struct PsString {
  const char *data;
  size_t size;
};

inline float ps_f32(uint64_t raw) { return std::bit_cast<float>(static_cast<uint32_t>(raw)); }
inline uint64_t ps_slot_f32(float value) { return static_cast<uint64_t>(std::bit_cast<uint32_t>(value)); }
inline double ps_f64(uint64_t raw) { return std::bit_cast<double>(raw); }
inline uint64_t ps_slot_f64(double value) { return std::bit_cast<uint64_t>(value); }
inline int64_t ps_s64(uint64_t value) { return static_cast<int64_t>(value); }

inline uint64_t ps_div_s64(uint64_t lhs, uint64_t rhs) {
  const int64_t divisor = ps_s64(rhs);
  if (divisor == 0) {
    ps_fault("division by zero in IR");
  }
  if (divisor == -1) {
    return uint64_t{0} - lhs;
  }
  return static_cast<uint64_t>(ps_s64(lhs) / divisor);
}

inline uint64_t ps_div_u64(uint64_t lhs, uint64_t rhs) {
  if (rhs == 0) {
    ps_fault("division by zero in IR");
  }
  return lhs / rhs;
}

// A line goes out with its newline in one call (stdio locks the stream for a call), so lines printed by different
// threads never mix within a line.
[[gnu::noinline]] void ps_emit_line(const char *text, size_t size, FILE *out) {
  char small[512];
  if (size < sizeof(small)) {
    std::memcpy(small, text, size);
    small[size] = '\n';
    std::fwrite(small, 1, size + 1, out);
    return;
  }
  std::string line;
  line.reserve(size + 1);
  line.append(text, size);
  line.push_back('\n');
  std::fwrite(line.data(), 1, line.size(), out);
}

inline void ps_emit(const char *text, size_t size, uint64_t flags) {
  FILE *out = (flags & 2) != 0 ? stderr : stdout;
  if ((flags & 1) != 0) {
    ps_emit_line(text, size, out);
    return;
  }
  std::fwrite(text, 1, size, out);
}

inline void ps_emit(std::string &&text, uint64_t flags) {
  if ((flags & 1) != 0) {
    text.push_back('\n');
  }
  std::fwrite(text.data(), 1, text.size(), (flags & 2) != 0 ? stderr : stdout);
}

// ---- strings -------------------------------------------------------------

inline const PsString &ps_string(const PsString *table, size_t count, uint64_t index) {
  if (index >= count) {
    ps_fault("invalid string index in IR");
  }
  return table[static_cast<size_t>(index)];
}

// A static text argument of a host call: the module's NUL-terminated string.
inline const char *ps_host_text(const PsString *table, size_t count, uint64_t index) {
  return ps_string(table, count, index).data;
}

// ---- heap and indirect addressing ----------------------------------------

// Blocks of this thread's arena that other threads freed are freed before the next allocation.
inline void ps_heap_drain(Rt &rt) {
  if (rt.heap.threaded() && rt.heap.hasRemoteFrees()) [[unlikely]] {
    std::string error;
    if (!drainRemoteFrees(rt.text, rt.heap, error)) {
      ps_fault(error);
    }
  }
}

inline uint64_t ps_heap_alloc_bytes(Rt &rt, uint64_t count) {
  ps_heap_drain(rt);
  uint64_t address = 0;
  std::string error;
  if (!rt.heap.allocateBytes(count, address, error)) {
    ps_fault(error);
  }
  return address;
}

inline uint64_t ps_heap_alloc(Rt &rt, uint64_t count) {
  ps_heap_drain(rt);
  uint64_t address = 0;
  std::string error;
  if (!rt.heap.allocate(count, address, error)) {
    ps_fault(error);
  }
  return address;
}

inline void ps_heap_free(Rt &rt, uint64_t address) {
  std::string error;
  if (!rt.heap.release(address, error)) {
    ps_fault(error);
  }
}

inline uint64_t ps_heap_realloc(Rt &rt, uint64_t address, uint64_t count) {
  ps_heap_drain(rt);
  uint64_t fresh = 0;
  std::string error;
  if (!rt.heap.reallocate(address, count, fresh, error)) {
    ps_fault(error);
  }
  return fresh;
}

// The slot of local `index` (in the VM's numbering of all live locals) in an enclosing frame, or null.
// It only reads, and says so: see ps_resolve.
[[gnu::noinline, gnu::pure]] uint64_t *ps_resolve_outer(const Rt &rt, uint64_t index) {
  for (unsigned i = rt.frameCount; i-- > 0;) {
    const PsFrameRef &outer = rt.frames[i];
    if (index >= outer.base) {
      if (index - outer.base < outer.count) {
        return outer.slots + (index - outer.base);
      }
      break;
    }
  }
  return nullptr;
}

// Resolves a byte address to the slot it names: a tagged heap address, or a
// local of this frame (`base` is its first local) or of an enclosing one.
// The calls on its rare paths (a slot of another arena, a local of an enclosing frame) are of functions marked pure,
// so a loop need not read rt.heap again after one. Keep its five arguments: with a sixth, or with a local for the
// heap in every function, the compiler stopped inlining small functions and strings/append_chunks ran 19% more
// instructions.
inline uint64_t *ps_resolve(Rt &rt, uint64_t *frame, uint64_t base, size_t frameCount, uint64_t address) {
  if (VmHeapCore::isByteAddress(address)) {
    ps_fault("slot access to a byte region in IR: " + std::to_string(address));
  }
  if (address % PsSlotBytes != 0) {
    ps_fault("unaligned indirect address in IR: " + std::to_string(address));
  }
  if ((address & PsHeapTag) != 0) {
    uint64_t *slot = rt.heap.slotAt(address);
    if (slot == nullptr) {
      ps_fault("invalid indirect address in IR: " + std::to_string(address));
    }
    return slot;
  }
  const uint64_t index = address / PsSlotBytes;
  if (index - base < frameCount) {
    return &frame[static_cast<size_t>(index - base)];
  }
  uint64_t *slot = ps_resolve_outer(rt, index);
  if (slot == nullptr) {
    ps_fault("invalid indirect address in IR: " + std::to_string(address));
  }
  return slot;
}

[[noreturn]] void ps_byte_fault(uint64_t address) {
  if ((address & PsHeapTag) != 0 && !VmHeapCore::isByteAddress(address)) {
    ps_fault("byte access to a slot region in IR: " + std::to_string(address));
  }
  ps_fault("invalid byte address in IR: " + std::to_string(address));
}

// A byte address names a byte of a byte region; a slot address (a u8 local or slot field) names its
// slot's low byte.
// byteAt checks the tag bits itself, so a byte of a live region needs no other test.
// The check stays out of line: inlined into the byte loops of a large function, strings/append_chunks took
// 15% more CPU time (as TODO-5840 found too).
[[gnu::noinline]] uint8_t *ps_byte_at(Rt &rt, uint64_t address) {
  return rt.heap.byteAt(address);
}

inline uint64_t ps_load_u8(Rt &rt, uint64_t *frame, uint64_t base, size_t frameCount, uint64_t address) {
  if (const uint8_t *byte = ps_byte_at(rt, address)) {
    return *byte;
  }
  if (!VmHeapCore::isByteAddress(address)) {
    return *ps_resolve(rt, frame, base, frameCount, address) & UINT64_C(0xff);
  }
  ps_byte_fault(address);
}

inline uint64_t ps_store_u8(Rt &rt, uint64_t *frame, uint64_t base, size_t frameCount, uint64_t address,
                           uint64_t raw) {
  const uint8_t value = static_cast<uint8_t>(raw & UINT64_C(0xff));
  if (uint8_t *byte = ps_byte_at(rt, address)) {
    *byte = value;
    return value;
  }
  if (!VmHeapCore::isByteAddress(address)) {
    *ps_resolve(rt, frame, base, frameCount, address) = value;
    return value;
  }
  ps_byte_fault(address);
}

// ---- text across the host boundary ----------------------------------------

// A Text argument of a host call: the NUL-terminated bytes of a String's data block (0 is empty text) or
// a module-table literal.
inline const char *ps_host_text_arg(Rt &rt, const PsString *table, size_t count, uint64_t slot) {
  if (slot == 0) {
    return "";
  }
  if (VmHeapCore::isByteAddress(slot)) {
    const uint8_t *first = rt.heap.byteAt(slot);
    if (first == nullptr) {
      ps_fault("invalid text address passed to host function");
    }
    return reinterpret_cast<const char *>(first);
  }
  if ((slot & PsHeapTag) == 0 && slot < count) {
    return table[static_cast<size_t>(slot)].data;
  }
  ps_fault("invalid text passed to host function");
}

// A BytePointer argument: the `length` bytes at a byte-region address, all in one live region, or a fault (address 0
// with length 0 is null).
inline uint8_t *ps_host_bytes(Rt &rt, uint64_t address, uint64_t length) {
  if (address == 0 && length == 0) {
    return nullptr;
  }
  uint8_t *first = rt.heap.byteSpan(address, length);
  if (first == nullptr) {
    ps_fault("invalid byte pointer passed to host function");
  }
  return first;
}

// A Text result: the returned text copied into a fresh string-heap block the program owns (0 for empty).
inline uint64_t ps_host_text_result(Rt &rt, const char *text) {
  const size_t size = text == nullptr ? 0 : std::strlen(text);
  if (size == 0) {
    return 0;
  }
  uint64_t block = 0;
  std::string error;
  if (!rt.text.allocate(rt.heap, size + 1, block, error)) {
    ps_fault(error);
  }
  std::memcpy(rt.heap.byteAt(block), text, size);
  return block;
}

// The `__pstext_*` host functions the runtime answers itself.
inline uint64_t ps_text_call(Rt &rt, const char *name, const uint64_t *args) {
  uint64_t result = 0;
  bool known = false;
  std::string error;
  if (!callTextHostFunction(rt.text, rt.heap, name, args, result, known, error)) {
    ps_fault(error);
  }
  if (!known) {
    ps_fault(std::string("unknown text host function ") + name);
  }
  return result;
}

// `__pstext_literal`: the address of a module string literal's bytes (a byte region made on first use).
inline uint64_t ps_text_literal(Rt &rt, const PsString *table, size_t count, uint64_t index) {
  const PsString &literal = ps_string(table, count, index);
  uint64_t address = 0;
  std::string error;
  if (!rt.text.literal(rt.heap, index, count, literal.data, literal.size, address, error)) {
    ps_fault(error);
  }
  return address;
}

// `__pstext_argument`: the entry argument at the index copied into a fresh string-heap block.
inline uint64_t ps_text_argument(Rt &rt, uint64_t raw) {
  const int64_t index = static_cast<int32_t>(raw);
  const char *argument = index >= 0 && index < rt.argc ? rt.argv[index] : "";
  return ps_host_text_result(rt, argument);
}

// ---- argv ----------------------------------------------------------------

inline void ps_print_argv(Rt &rt, uint64_t rawIndex, uint64_t flags, bool unsafe) {
  const int64_t index = ps_s64(rawIndex);
  if (index < 0 || index >= rt.argc) {
    if (unsafe) {
      return;
    }
    ps_fault("invalid argv index in IR");
  }
  const char *text = rt.argv[index];
  ps_emit(text, std::strlen(text), flags);
}

// ---- files ---------------------------------------------------------------

inline uint32_t ps_io_error() {
  return errno == 0 ? 1u : static_cast<uint32_t>(errno);
}

inline uint64_t ps_pack_handle(int fd) {
  if (fd < 0) {
    return static_cast<uint64_t>(ps_io_error()) << 32;
  }
  return static_cast<uint64_t>(static_cast<uint32_t>(fd));
}

inline int ps_handle_fd(uint64_t handle) {
  return static_cast<int>(handle & 0xffffffffu);
}

// mode: 0 read, 1 write (create, truncate), 2 append (create).
inline uint64_t ps_file_open(const PsString &path, int mode) {
  const int flags = mode == 1 ? (O_WRONLY | O_CREAT | O_TRUNC) : (mode == 2 ? (O_WRONLY | O_CREAT | O_APPEND) : O_RDONLY);
  const std::string text(path.data, path.size);
  return ps_pack_handle(::open(text.c_str(), flags, 0644));
}

inline uint64_t ps_file_close(uint64_t handle) {
  return ::close(ps_handle_fd(handle)) < 0 ? static_cast<uint64_t>(ps_io_error()) : 0u;
}

inline uint64_t ps_file_flush(uint64_t handle) {
  return ::fsync(ps_handle_fd(handle)) < 0 ? static_cast<uint64_t>(ps_io_error()) : 0u;
}

inline uint64_t ps_file_read_byte(uint64_t handle, uint64_t &local) {
  uint8_t value = 0;
  const ssize_t rc = ::read(ps_handle_fd(handle), &value, 1);
  if (rc < 0) {
    return ps_io_error();
  }
  if (rc == 0) {
    return PsFileReadEof;
  }
  local = static_cast<uint64_t>(value);
  return 0;
}

inline uint64_t ps_write_all(uint64_t handle, const void *data, size_t size) {
  const char *cursor = static_cast<const char *>(data);
  size_t remaining = size;
  while (remaining > 0) {
    const ssize_t wrote = ::write(ps_handle_fd(handle), cursor, remaining);
    if (wrote < 0) {
      return ps_io_error();
    }
    if (wrote == 0) {
      return static_cast<uint64_t>(EIO);
    }
    remaining -= static_cast<size_t>(wrote);
    cursor += wrote;
  }
  return 0;
}

inline uint64_t ps_file_write_text(uint64_t handle, const std::string &text) {
  return ps_write_all(handle, text.data(), text.size());
}

inline uint64_t ps_file_write_byte(uint64_t handle, uint64_t raw) {
  const uint8_t value = static_cast<uint8_t>(raw & 0xffu);
  return ps_write_all(handle, &value, 1);
}

inline uint64_t ps_file_write_newline(uint64_t handle) {
  const char newline = '\n';
  return ps_write_all(handle, &newline, 1);
}

} // namespace

)CPP";

// Tasks on threads (docs/MultithreadingPrototype.md, Runtime Model), written inside the program's unnamed
// namespace when the module has task opcodes. A spawned task is one OS thread with an `Rt` of its own: call depth
// and local numbering start at 0, as on the VM (a local address means nothing on another stack), and its heap is an
// arena the spawner acquired for it. The handle has the VM's encoding (a tag in bits 48-62, the slot's generation in
// bits 32-47, the slot in bits 0-31) and the VM's faults.
inline constexpr const char *OptCppTaskRuntime = R"CPP(
constexpr uint64_t PsTaskHandleTag = uint64_t{0x7A5C} << 48;
constexpr uint64_t PsTaskHandleTagMask = uint64_t{0xFFFF} << 48;
constexpr size_t PsMaxLiveTasks = size_t{1} << 20;
// The main thread's stack size: a task may recurse as deep as the entry function (PsMaxCallDepth), and its Rt is
// on its stack. The default of a secondary thread is 512 KiB on macOS.
constexpr size_t PsTaskStackBytes = size_t{8} << 20;

using PsTaskEntry = uint64_t (*)(Rt &, const uint64_t *);

struct PsTask {
  pthread_t thread{};
  PsTaskEntry entry = nullptr;
  int argc = 0;
  char **argv = nullptr;
  VmHeapArenas *arenas = nullptr;
  VmHeapArena *arena = nullptr;
  uint64_t result = 0;
  std::vector<uint64_t> arguments;
};

struct PsTaskSlot {
  PsTask *task = nullptr;
  uint16_t generation = 0;
};

struct PsTasks {
  std::mutex lock;
  std::vector<PsTaskSlot> slots;
  std::vector<size_t> freeSlots;
};

// Never destroyed: the process may end while tasks still run.
PsTasks &ps_tasks() {
  static PsTasks *tasks = new PsTasks();
  return *tasks;
}

void *ps_task_main(void *raw) {
  PsTask &task = *static_cast<PsTask *>(raw);
  Rt rt{task.argc, task.argv, 0, task.arena->core, task.arena->text, *task.arenas};
  task.result = task.entry(rt, task.arguments.data());
  // The arena's live blocks stay valid: a result the task allocated is freed by whoever holds it.
  task.arenas->release(task.arena);
  return nullptr;
}

// TaskSpawn: the arguments are copied into the task block, and the task starts on a thread of its own.
uint64_t ps_task_spawn(Rt &rt, PsTaskEntry entry, const uint64_t *arguments, size_t count) {
  PsTask *task = new PsTask();
  task->entry = entry;
  task->argc = rt.argc;
  task->argv = rt.argv;
  task->arenas = &rt.arenas;
  task->arguments.assign(arguments, arguments + count);
  uint64_t handle = 0;
  {
    PsTasks &tasks = ps_tasks();
    std::lock_guard<std::mutex> guard(tasks.lock);
    if (tasks.slots.size() - tasks.freeSlots.size() >= PsMaxLiveTasks) {
      ps_fault("too many live tasks");
    }
    size_t slot = 0;
    if (!tasks.freeSlots.empty()) {
      slot = tasks.freeSlots.back();
      tasks.freeSlots.pop_back();
    } else {
      slot = tasks.slots.size();
      tasks.slots.emplace_back();
    }
    tasks.slots[slot].task = task;
    handle = PsTaskHandleTag | (static_cast<uint64_t>(tasks.slots[slot].generation) << 32) |
             static_cast<uint64_t>(slot);
  }
  // The arena is acquired here, not on the new thread: the first call moves the main arena's storage into its
  // reservation, which must happen while this is the only thread.
  std::string error;
  task->arena = rt.arenas.acquire(error);
  if (task->arena == nullptr) {
    ps_fault(error);
  }
  pthread_attr_t attributes;
  int rc = pthread_attr_init(&attributes);
  if (rc == 0) {
    rc = pthread_attr_setstacksize(&attributes, PsTaskStackBytes);
    if (rc == 0) {
      // Nobody else has the handle yet, so nothing reads task->thread before pthread_create has written it.
      rc = pthread_create(&task->thread, &attributes, ps_task_main, task);
    }
    pthread_attr_destroy(&attributes);
  }
  if (rc != 0) {
    ps_fault(std::string("cannot start a task thread: ") + std::strerror(rc));
  }
  return handle;
}

// TaskWait: joins the task's thread, copies the result out and frees the task block. The handle is consumed.
uint64_t ps_task_wait(uint64_t handle) {
  PsTask *task = nullptr;
  {
    PsTasks &tasks = ps_tasks();
    std::lock_guard<std::mutex> guard(tasks.lock);
    const size_t slot = static_cast<size_t>(handle & UINT64_C(0xFFFFFFFF));
    const uint16_t generation = static_cast<uint16_t>((handle >> 32) & UINT64_C(0xFFFF));
    if ((handle & PsTaskHandleTagMask) != PsTaskHandleTag || slot >= tasks.slots.size()) {
      ps_fault("invalid task handle in IR");
    }
    PsTaskSlot &entry = tasks.slots[slot];
    if (entry.task == nullptr || entry.generation != generation) {
      ps_fault("task handle already waited");
    }
    task = entry.task;
    entry.task = nullptr;
    entry.generation = static_cast<uint16_t>(entry.generation + 1);
    tasks.freeSlots.push_back(slot);
  }
  const int rc = pthread_join(task->thread, nullptr);
  if (rc != 0) {
    ps_fault(std::string("cannot join a task thread: ") + std::strerror(rc));
  }
  const uint64_t result = task->result;
  delete task;
  return result;
}

)CPP";

// The atomic opcodes (docs/spec/vm-design.md, Atomics), written inside the program's unnamed namespace when the
// module has one. Each works on one heap slot through std::atomic_ref (the compiler's atomic builtins where the
// standard library has no atomic_ref yet), sequentially consistent. A 32-bit operation keeps the slot sign-extended,
// as the VM does.
inline constexpr const char *OptCppAtomicRuntime = R"CPP(
#if defined(__cpp_lib_atomic_ref)
using PsAtomicSlot = std::atomic_ref<uint64_t>;
#else
struct PsAtomicSlot {
  uint64_t *slot;
  explicit PsAtomicSlot(uint64_t &value) : slot(&value) {}
  uint64_t load() const { return __atomic_load_n(slot, __ATOMIC_SEQ_CST); }
  void store(uint64_t value) const { __atomic_store_n(slot, value, __ATOMIC_SEQ_CST); }
  uint64_t exchange(uint64_t value) const { return __atomic_exchange_n(slot, value, __ATOMIC_SEQ_CST); }
  uint64_t fetch_add(uint64_t delta) const { return __atomic_fetch_add(slot, delta, __ATOMIC_SEQ_CST); }
  bool compare_exchange_strong(uint64_t &expected, uint64_t desired) const {
    return __atomic_compare_exchange_n(slot, &expected, desired, false, __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST);
  }
};
#endif

inline uint64_t ps_atomic_value(uint64_t value, bool narrow) {
  return narrow ? static_cast<uint64_t>(static_cast<int64_t>(static_cast<int32_t>(value))) : value;
}

inline uint64_t ps_atomic_load(uint64_t *slot, bool narrow) {
  return ps_atomic_value(PsAtomicSlot(*slot).load(), narrow);
}

inline void ps_atomic_store(uint64_t *slot, uint64_t value, bool narrow) {
  PsAtomicSlot(*slot).store(ps_atomic_value(value, narrow));
}

inline uint64_t ps_atomic_add(uint64_t *slot, uint64_t delta, bool narrow) {
  PsAtomicSlot atomic(*slot);
  if (!narrow) {
    return atomic.fetch_add(delta);
  }
  uint64_t before = atomic.load();
  while (!atomic.compare_exchange_strong(before, ps_atomic_value(before + delta, true))) {
  }
  return ps_atomic_value(before, true);
}

inline uint64_t ps_atomic_exchange(uint64_t *slot, uint64_t value, bool narrow) {
  return ps_atomic_value(PsAtomicSlot(*slot).exchange(ps_atomic_value(value, narrow)), narrow);
}

inline uint64_t ps_atomic_compare_exchange(uint64_t *slot, uint64_t expected, uint64_t desired, bool narrow) {
  uint64_t held = ps_atomic_value(expected, narrow);
  return PsAtomicSlot(*slot).compare_exchange_strong(held, ps_atomic_value(desired, narrow)) ? 1 : 0;
}

)CPP";

// The mutex opcodes (docs/spec/vm-design.md, Mutexes), written after OptCppAtomicRuntime when the module has one.
// The lock is its heap slot: 0 while free, the holder (the address of its thread's Rt) otherwise. Taking a free lock
// and freeing one nobody waits for is one atomic operation on the slot. A thread that finds the lock held sleeps on
// one condition variable of the program, which an unlock signals when any thread sleeps.
inline constexpr const char *OptCppMutexRuntime = R"CPP(
struct PsLockWaits {
  pthread_mutex_t gate = PTHREAD_MUTEX_INITIALIZER;
  pthread_cond_t changed = PTHREAD_COND_INITIALIZER;
  // The threads that sleep or are about to. Written with the gate held, read by an unlock without it.
  std::atomic<uint64_t> sleepers{0};
};

// Never destroyed: the process may end while tasks still run.
PsLockWaits &ps_lock_waits() {
  static PsLockWaits *waits = new PsLockWaits();
  return *waits;
}

[[gnu::noinline]] void ps_mutex_lock_slow(PsAtomicSlot lock, uint64_t holder) {
  PsLockWaits &waits = ps_lock_waits();
  pthread_mutex_lock(&waits.gate);
  // Counted before the lock is tried again: an unlock that frees it after this try sees the sleeper and signals.
  waits.sleepers.fetch_add(1);
  for (;;) {
    uint64_t held = 0;
    if (lock.compare_exchange_strong(held, holder)) {
      break;
    }
    pthread_cond_wait(&waits.changed, &waits.gate);
  }
  waits.sleepers.fetch_sub(1);
  pthread_mutex_unlock(&waits.gate);
}

inline void ps_mutex_lock(Rt &rt, uint64_t *slot) {
  const uint64_t holder = reinterpret_cast<uint64_t>(&rt);
  PsAtomicSlot lock(*slot);
  uint64_t held = 0;
  if (lock.compare_exchange_strong(held, holder)) {
    return;
  }
  if (held == holder) {
    ps_fault("mutex locked again by the task that holds it");
  }
  ps_mutex_lock_slow(lock, holder);
}

inline void ps_mutex_unlock(Rt &rt, uint64_t *slot) {
  PsAtomicSlot lock(*slot);
  if (lock.load() != reinterpret_cast<uint64_t>(&rt)) {
    ps_fault("mutex unlocked by a task that does not hold it");
  }
  lock.store(0);
  PsLockWaits &waits = ps_lock_waits();
  if (waits.sleepers.load() != 0) {
    pthread_mutex_lock(&waits.gate);
    pthread_cond_broadcast(&waits.changed);
    pthread_mutex_unlock(&waits.gate);
  }
}

)CPP";

} // namespace primec
